import {INSTRUMENTS,DEFAULT_SETTINGS,DEFAULT_PLAYBOOK,risk,aggregateCandles,executionSummary,round,planWarnings} from './domain.js';
import {MARKET_NAMES,radarNews,newsTimestamp,eventRelevance,CONTEXT_TIME_ZONE,berlinTime,sourceDateLabel,calendarTimestamp,calendarTime,compareCalendar,newsTime} from './news-context.js';
import {TradingChart} from './chart.js';
const $=(s,r=document)=>r.querySelector(s),$$=(s,r=document)=>[...r.querySelectorAll(s)];
const esc=x=>String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const cash=x=>x===null||x===undefined?'—':new Intl.NumberFormat('de-DE',{style:'currency',currency:'USD',maximumFractionDigits:2}).format(x);
const number=(x,n=2)=>x===null||x===undefined?'—':new Intl.NumberFormat('de-DE',{maximumFractionDigits:n}).format(x);
let state={plans:[],executions:[],reviews:[],news:[],events:[],observations:[],context:[],attachments:[],series:[],drawings:[],playbooks:[DEFAULT_PLAYBOOK],snapshots:[],estimates:[],proposals:[],settings:DEFAULT_SETTINGS,providers:{},metrics:{}},view='overview',instrument='MGC',chart=null,chartBars=[],timeframe=15,selectedPlan=null,replay=100,loading=false;
const date=x=>x?new Intl.DateTimeFormat('de-DE',{timeZone:state.settings.timezone||'Europe/Berlin',day:'2-digit',month:'2-digit',hour:'2-digit',minute:'2-digit'}).format(new Date(x)):'Zeit unbekannt';
const time=x=>x?new Intl.DateTimeFormat('de-DE',{timeZone:state.settings.timezone||'Europe/Berlin',hour:'2-digit',minute:'2-digit'}).format(new Date(x)):'—';
function localValue(x=new Date(),seconds=false){const d=new Date(x);return new Date(d.getTime()-d.getTimezoneOffset()*60000).toISOString().slice(0,seconds?23:16);}
function formTime(v){if(!v)throw Error('Zeit fehlt.');return new Date(v).toISOString();}
function notify(msg,error=false){const el=$('#toast');el.textContent=msg;el.hidden=false;el.style.background=error?'#48242d':'#263d35';clearTimeout(notify.timer);notify.timer=setTimeout(()=>el.hidden=true,error?8500:4500);}
function apiURL(resource,query={}){return '/api/trading?'+new URLSearchParams({resource,...query});}
const pendingCommands=new Map();
async function api(resource,body,query={},method){const fingerprint=body?JSON.stringify([resource,method||'POST',body]):null;const opts={method:method||(body?'POST':'GET'),credentials:'same-origin',headers:{'X-Trading-Client':'marcel-ipad'}};if(body){opts.headers['Content-Type']='application/json';if(!pendingCommands.has(fingerprint))pendingCommands.set(fingerprint,crypto.randomUUID());opts.headers['X-Idempotency-Key']=pendingCommands.get(fingerprint);opts.body=JSON.stringify(body);}const r=await fetch(apiURL(resource,query),opts);const j=await r.json();if(!r.ok||j.ok===false){const e=new Error(j.error||`HTTP ${r.status}`);e.status=r.status;if(r.status<500)pendingCommands.delete(fingerprint);throw e;}if(fingerprint)pendingCommands.delete(fingerprint);return j.result??j;}
const chip=(x,cls='')=>`<span class="chip ${cls}">${esc(x)}</span>`;
const empty=(title,description,button='')=>`<div class="empty-block"><div class="empty-icon">◇</div><strong>${esc(title)}</strong><span>${esc(description)}</span>${button}</div>`;
const button=(action,label,cls='',id='')=>`<button type="button" class="${cls}" data-action="${action}"${id?` data-id="${esc(id)}"`:''}>${label}</button>`;
const header=(title,subtitle,actions='')=>`<div class="section-intro"><div><h2>${esc(title)}</h2><p>${esc(subtitle)}</p></div><div class="row">${actions}</div></div>`;
const panel=(title,body,extra='')=>`<section class="panel"${title.startsWith('NEWS RADAR')?' data-context-panel="news"':title==='Market Context'?' data-context-panel="market"':title==='Wirtschaftskalender'?' data-context-panel="calendar"':title==='Quellenstatus'?' data-context-panel="sources"':''}><div class="panel-head"><h2>${title}</h2>${title.startsWith('NEWS RADAR')||['Market Context','Wirtschaftskalender'].includes(title)?'<small class="muted" title="Europe/Berlin · Sommer-/Winterzeit automatisch">Zeiten: Berlin</small>':''}${extra}</div>${body}</section>`;
const options=(values,selected)=>values.map(x=>{const [v,l]=Array.isArray(x)?x:[x,x];return `<option value="${esc(v)}"${v===selected?' selected':''}>${esc(l)}</option>`;}).join('');
const field=(name,label,value='',type='text',extra='')=>`<div class="form-field"><label for="f-${name}">${label}</label><input id="f-${name}" name="${name}" type="${type}" value="${esc(value)}" ${extra}></div>`;
const select=(name,label,vals,value)=>`<div class="form-field"><label for="f-${name}">${label}</label><select id="f-${name}" name="${name}">${options(vals,value)}</select></div>`;
const textarea=(name,label,value='',cls='full')=>`<div class="form-field ${cls}"><label for="f-${name}">${label}</label><textarea id="f-${name}" name="${name}">${esc(value)}</textarea></div>`;
function bestSeries(root=instrument){const configured=state.settings.contracts?.[root];const all=state.series.filter(s=>configured?s.contract===configured:s.contract.startsWith(root));return all.sort((a,b)=>b.last.localeCompare(a.last)||a.resolution-b.resolution)[0]||null;}
function currentContract(root=instrument){return state.settings.contracts?.[root]||bestSeries(root)?.contract||'';}
function actual(p){return executionSummary(p,state.executions.filter(e=>e.planId===p.id));}
function planState(p){const a=actual(p);if(a.status==='OPEN')return {text:`BESTÄTIGT OFFEN · ${a.openQuantity}`,cls:'green'};if(a.status==='CLOSED')return {text:'ABGESCHLOSSEN',cls:a.net>=0?'green':'red'};const r=state.reviews.find(r=>r.planId===p.id&&['CANCELLED','NO_FILL'].includes(r.kind));if(r)return {text:r.kind==='CANCELLED'?'STORNIERT':'KEIN FILL',cls:''};if(Date.parse(p.expiresAt)<Date.now())return {text:'ABGELAUFEN · REVIEW',cls:''};return {text:'WARTET AUF RETEST',cls:'gold'};}
function seriesStatus(s){if(!s)return 'Kein Feed';const age=Date.now()-Date.parse(s.last)-s.resolution*1000;if(s.source==='databento-live'&&age<150000)return 'Livebars · '+time(s.last);return 'Stand '+date(s.last);}
function tickers(){const entries=['MGC','MNQ','MYM'].map(k=>{const s=bestSeries(k);return `<button class="ticker ${instrument===k?'active':''}" data-instrument="${k}"><div class="t-head"><b>${esc(INSTRUMENTS[k].name)}</b><span>${k}</span></div><div class="value">${number(s?.price,2)}</div><small>${esc(seriesStatus(s))}</small></button>`;});const dxy=state.observations.find(o=>o.id==='DTWEXBGS'),yield10=state.observations.find(o=>o.id==='DGS10'),oil=bestSeries('MCL');entries.push(`<div class="ticker"><div class="t-head"><b>Broad USD Index</b><span>FED H.10</span></div><div class="value">${number(dxy?.value,2)}</div><small>${dxy?esc(dxy.source+' · '+date(dxy.at)):'Noch kein H.10-Wert'}</small></div>`,`<div class="ticker"><div class="t-head"><b>US 10Y</b><span>RENDITEN</span></div><div class="value">${yield10?number(yield10.value,2)+' %':'—'}</div><small>${yield10?'Tageswert · '+date(yield10.at):'Noch kein Treasury-Tageswert'}</small></div>`,`<button class="ticker" data-instrument="MCL"><div class="t-head"><b>WTI-Öl</b><span>MCL</span></div><div class="value">${number(oil?.price,2)}</div><small>${esc(seriesStatus(oil))}</small></button>`);$('#tickers').innerHTML=entries.join('');}
const tfLabel=t=>t<60?'M'+t:t<1440?'H'+(t/60):'D'+(t/1440);
function chartPanel(){const s=bestSeries();return `<section class="panel chart-panel"><div class="panel-head chart-head"><div class="chart-title"><b>${esc(INSTRUMENTS[instrument].name)}</b> ${chip(currentContract()||'KONTRAKT FEHLT')}<small id="chart-source">${esc(s?`${s.source} · ${seriesStatus(s)}`:'Keine künstlichen Kurse. Import oder Datenzugang erforderlich.')}</small></div><div class="chart-controls">${[1,5,15,30,60,240,1440].map(t=>`<button data-tf="${t}" ${s&&t*60<s.resolution?'disabled title="Quelle ist gröber"':''} class="${timeframe===t?'selected':''}">${tfLabel(t)}</button>`).join('')}</div></div><div class="chart-controls panel-body" style="padding:8px 12px;border-bottom:1px solid #222d3a"><select class="filter" id="chart-market" aria-label="Chartmarkt">${options(Object.entries(INSTRUMENTS).map(([k,v])=>[k,v.name]),instrument)}</select><select class="filter" id="chart-side" aria-label="Zonenrichtung"><option value="LONG">Demand</option><option value="SHORT">Supply</option></select>${button('chart-pan','↔ Bewegen')}${button('chart-zone','▱ Block')}${button('chart-line','— Linie')}${button('chart-path','✎ Zeichnen')}${button('chart-undo','↶')}${button('chart-in','＋')}${button('chart-out','−')}${button('chart-reset','Einpassen')}${button('chart-save','Bild')}</div><div class="chart-frame" id="chart-host"></div><div class="chart-bottom"><span id="chart-note">Exakter Kontrakt · OHLCV · keine Orderausführung</span><div class="row"><label for="replay">Replay</label><input id="replay" type="range" min="5" max="100" value="${replay}" aria-label="Replay-Zeitpunkt">${button('replay-step','▸ Schritt')}</div></div></section>`;}
function marketContext(){
 const manual=state.context.find(x=>x.instrument===instrument),m=state.marketContexts?.[instrument]||(instrument==='MGC'?state.marketContext:null);
 const observations=state.observations.filter(o=>(m?.observationIds||['DGS2','DGS10','DFII10','DTWEXBGS','T2S10S']).includes(o.id));
 const cells=observations.map(o=>`<div class="context-cell"><span>${esc(o.label)}</span><b>${number(o.value, o.id==='DTWEXBGS'?4:2)} ${esc(o.unit)}</b><small>${esc(o.observation_date?sourceDateLabel(o.observation_date):berlinTime(o.at))} · ${esc(o.source)}</small><small>${o.change_bps!=null?'Δ '+number(o.change_bps)+' bp':o.change!=null?'Δ '+number(o.change,4):'Vergleich fehlt'}${o.id==='DTWEXBGS'?' · wöchentlich veröffentlicht':''}</small></div>`).join('');
 const regimes=m?(m.regimes||[['Rates',m.rates],['USD',m.usd],['Oil',m.oil],['Risk regime',m.risk],['Geopolitics',m.geopolitical],['Calendar 24h',m.calendar24h]]).map(([k,v])=>`<div class="context-cell"><span>${k}</span><b>${esc(v)}</b></div>`).join(''):'';
 return panel('Market Context',`<div class="panel-body"><div class="row"><b>${MARKET_NAMES[instrument]} MACRO BIAS</b>${chip(m?.bias||m?.goldBias||'NEUTRAL','gold')}</div><div class="context-grid">${cells||'<p class="muted">Makrodaten noch nicht geladen.</p>'}${instrument==='MCL'?`<div class="context-cell"><span>MCL / WTI</span><b>${number(m?.values?.oil?.value)}</b><small>${esc(m?.values?.oil?.at?berlinTime(m.values.oil.at):'Nicht verfügbar')}</small></div>`:''}${regimes}</div><p class="note">${esc(m?.explanation||(m?.reasons||['Keine Datenbasis für eine Richtung.']).join(' '))}</p>${(m?.warnings||[]).map(w=>`<p class="stat-warning">${esc(w)}</p>`).join('')}${m?.nextHigh?`<p>Nächster HIGH-Termin: ${esc(m.nextHigh.title)} · ${esc(eventTime(m.nextHigh))}</p>`:''}<p class="muted">Regelbasierter Kontext, keine Kursprognose. Futures: letzter vorhandener UTC-Tagesabschluss, kein Livefeed.</p><hr><div class="row"><span>MANUELLER BIAS</span>${chip(manual?.bias||'NEUTRAL')}</div><p class="note">${esc(manual?.thesis||'Keine manuelle These gespeichert.')}</p>${manual?.counterArgument?`<p class="muted">Gegenargument: ${esc(manual.counterArgument)}</p>`:''}</div>`,button('context','Bearbeiten'));
}
let newsMode='relevant';
const newsDate=newsTime;
function miniNews(){const items=radarNews(state.news,instrument,newsMode).slice(0,15);const filters=`<div class="row panel-body">${[['relevant','Relevant'],['all','Alle'],['macro','Macro'],['geo','Geopolitik']].map(([k,v])=>button('news-filter',v,newsMode===k?'selected':'',k)).join('')}</div>`;return panel('NEWS RADAR · '+MARKET_NAMES[instrument],filters+'<div class="news-scroll">'+(items.length?items.map(n=>`<div class="news-mini"><small title="${esc(newsTimestamp(n)?'UTC: '+new Date(newsTimestamp(n)).toISOString():'Zeit unbekannt')}">${esc(n.source)} · ${newsDate(n)}</small><a href="${esc(n.url)}" target="_blank" rel="noopener noreferrer">${esc(n.title)}</a><small>${esc((n.topics||[n.topic]).join(' · '))} · ${esc(n.relevance||'UNCLASSIFIED')}</small></div>`).join(''):empty('Keine relevanten Meldungen geladen','Fehlende News sind kein Nachweis geringer Risiken.'))+'</div>',button('news-add','＋'));}
let calendarMode='7d';
const eventTime=calendarTime;
function visibleCalendar(limit=100){const now=Date.now(),localDay=x=>new Intl.DateTimeFormat('en-CA',{timeZone:CONTEXT_TIME_ZONE,year:'numeric',month:'2-digit',day:'2-digit'}).format(new Date(x));return state.events.filter(e=>{
 const stamp=calendarTimestamp(e),dateOnly=stamp===null;
 if(dateOnly?(sourceDateLabel(e.scheduled_date)==='Datum unbekannt'||e.scheduled_date<localDay(now)):stamp<now)return false;
 if(calendarMode==='today')return dateOnly?e.scheduled_date===localDay(now):localDay(stamp)===localDay(now);
 if(calendarMode==='24h')return dateOnly?e.scheduled_date<=localDay(now+86400000):stamp<=now+86400000;
 return (dateOnly?e.scheduled_date<=localDay(now+7*86400000):stamp<=now+7*86400000)&&(calendarMode!=='high'||e.impact==='HIGH');
 }).sort(compareCalendar).slice(0,limit);}
function eventList(limit=5){const events=visibleCalendar(limit);if(limit<=5)return events.length?events.map(e=>`<div class="event"><time>${esc(calendarTimestamp(e)!==null?berlinTime(calendarTimestamp(e),'clock'):'—')}</time><div><b>${esc(e.title)}</b><small>${esc(eventTime(e))} · ${esc(e.source)} · ${esc(eventRelevance(e,instrument))} · ${MARKET_NAMES[instrument]}</small></div></div>`).join(''):empty('Keine Termine im gewählten Fenster','Quellenstatus beachten.');return events.length?`<div class="table-wrap"><table><thead><tr><th>Zeit</th><th>Land</th><th>Event</th><th>Importance*</th><th>Actual</th><th>Forecast</th><th>Previous</th></tr></thead><tbody>${events.map(e=>`<tr><td>${esc(eventTime(e))}</td><td>${esc(e.country)}</td><td><a href="${esc(e.source_url||e.url||'#')}" target="_blank" rel="noopener noreferrer">${esc(e.title)}</a><small>${esc(e.source)}${e.reference_period?' · '+esc(e.reference_period):''}</small></td><td>${chip(eventRelevance(e,instrument))}<small>${MARKET_NAMES[instrument]} · Basis ${esc(e.impact)}</small></td><td>${esc(e.actual??'—')}</td><td>${esc(e.forecast??'—')}</td><td>${esc(e.previous??'—')}</td></tr>`).join('')}</tbody></table></div><p class="muted">* Interne Trading-Relevanz. Keine erfundenen Konsenswerte. Zeiten: Berlin (Europe/Berlin).</p>`:empty('Keine Termine im gewählten Fenster','Quellenstatus beachten: Das beweist nicht, dass keine Ereignisse anstehen.');}
function planCard(p){const r=risk(p),status=planState(p),estimate=state.estimates.find(e=>e.planId===p.id),a=actual(p);return `<article class="plan-card"><div class="plan-top"><strong>${esc(INSTRUMENTS[p.instrument].name)} <span class="${p.side==='LONG'?'up':'down'}">${p.side}</span></strong>${chip(status.text,status.cls)}</div><div class="plan-data"><div><span>LIMIT · ${esc(p.contract)}</span><b>${number(p.entry,2)}</b></div><div><span>STOP · ${r.stopUnits} ${r.unit}</span><b>${number(p.stop,2)}</b></div><div><span>ZIEL · ${r.targetUnits} ${r.unit}</span><b>${number(p.target,2)}</b></div><div><span>${p.quantity} KONTRAKTE · ${number(r.rr)}R</span><b class="gold">${cash(r.riskWithCosts)} Risiko</b></div></div><div class="plan-foot"><span>${estimate?.fill?'Preisberührung geschätzt · ':''}${p.retrospective?'RÜCKBLICK · ':''}${a.status==='CLOSED'?cash(a.net):'Gültig bis '+date(p.expiresAt)}</span>${button('detail','Plan öffnen ↗','',p.id)}</div></article>`;}
function overview(){
 const active=state.plans.filter(p=>!['ABGESCHLOSSEN','STORNIERT','KEIN FILL'].includes(planState(p).text)).slice(0,3);
 const phasePlans=state.plans.filter(p=>p.phase===state.settings.phase&&!p.retrospective);
 const phaseNet=phasePlans.reduce((n,p)=>n+(actual(p).status==='CLOSED'?actual(p).net:0),0);
 return `<div class="overview-grid"><div class="overview-chart">${chartPanel()}</div><div class="overview-context">${marketContext()}</div><div class="overview-news stack">${miniNews()}${panel('Wirtschaftskalender',`<div class="stat-warning">${state.sync?.calendarStatus==='OK'?'Quelle synchronisiert · '+berlinTime(state.sync.lastSyncAt):'Kalenderabdeckung nicht bestätigt'}</div><div class="calendar-list">${eventList(2)}</div>`)}</div></div>
 <div class="active-strip">${panel('Aktive Trade-Pläne',active.length?active.map(planCard).join(''):empty('Der Markt muss zu deinem Preis kommen.','Noch kein Limit-Plan gespeichert.',button('new-plan','＋ Ersten Plan erstellen','gold-button')),chip('LIMIT ONLY','gold'))}</div>
 <div class="lower-grid">${panel('Performance · bestätigt',`<div class="panel-body">${metricCards(true)}<div class="row"><span class="muted">${esc(state.settings.phase)} · ${cash(phaseNet)} / ${cash(state.settings.phaseTarget)} persönliches Ziel</span></div><div class="muted">Echte Ergebnisse nur nach deiner Bestätigung. Schätzungen und Rückblicke bleiben getrennt.</div></div>`)}${panel('Session & Übergabe',`<div class="panel-body quick-actions">${button('review-morning','<span>☀</span> Morgenreview')}${button('context','<span>☾</span> Abend-Bias festhalten')}${button('report','<span>↓</span> Protokoll herunterladen')}${button('no-trade','<span>◇</span> Kein Setup dokumentieren')}</div>`)}</div>`;
}
function metricCards(compact=false){const m=state.metrics;return `<div class="metrics-grid"${compact?' style="margin:0 0 10px;gap:8px"':''}>${[['Netto-P&L',cash(m.net||0),'Nur abgeschlossen'],['Trefferquote',m.winrate===null||m.winrate===undefined?'—':number(m.winrate,1)+' %',`${m.closed||0} bestätigte Trades`],['Ø Ergebnis',m.averageR===null||m.averageR===undefined?'—':number(m.averageR)+'R','Nach erfassten Kosten'],['Fill-Rate',m.fillRate===null||m.fillRate===undefined?'—':number(m.fillRate,1)+' %',`${m.confirmedFills||0} / ${m.planned||0} Pläne`]].map(([label,val,note])=>`<div class="metric"><label>${label}</label><strong${label==='Netto-P&L'?` class="${(m.net||0)>=0?'up':'down'}"`:''}>${val}</strong><small>${note}</small></div>`).join('')}</div>`;}
function planView(){return header('Trade-Pläne','Plan ≠ Ausführung. Decision Snapshots werden nach dem Speichern nicht verändert.',button('new-plan','＋ Limit planen','gold-button'))+`<div class="grid-2">${state.plans.length?state.plans.map(p=>panel(`${esc(p.contract)} · ${date(p.plannedAt)}`,planCard(p))).join(''):panel('Limit-only',empty('Noch kein Plan','Entry, SL, TP und Grund werden vorab festgehalten.'))}</div>`;}
function journal(){return header('Journal','Manuelle Fills, Morgenreviews und ungefüllte Ideen. Keine automatische Broker-Abfrage.',button('review','＋ Review')+button('report','Protokoll ↓')+button('export-csv','CSV ↓'))+metricCards()+`<div class="grid-2"><div class="stack">${panel('Trades & Pläne',state.plans.length?`<div class="table-wrap"><table><thead><tr><th>Kontrakt</th><th>Richtung</th><th>Status</th><th>Netto</th><th></th></tr></thead><tbody>${state.plans.map(p=>{const a=actual(p);return `<tr><td>${esc(p.contract)}</td><td class="${p.side==='LONG'?'up':'down'}">${p.side}</td><td>${esc(planState(p).text)}</td><td>${a.status==='NOT_CONFIRMED'?'—':cash(a.net)}</td><td>${button('detail','Öffnen','',p.id)}</td></tr>`;}).join('')}</tbody></table></div>`:empty('Noch keine Trades','Eine berührte Limit-Zone ist noch kein bestätigter Fill.'))}</div><div class="stack">${panel('Reviews & No Trades',state.reviews.length?state.reviews.slice(0,25).map(r=>`<article class="review-card"><h3>${esc(r.kind)}</h3><small>${date(r.createdAt)}</small><p>${esc(r.note||'Ohne Notiz')}</p>${r.planId?button('detail','Zum Plan','',r.planId):''}</article>`).join(''):empty('Reflektieren statt rückwirkend umdeuten','Nachts Plan; morgens neuer Review.'))}</div></div>`;}
function analyticsView(){const m=state.metrics,counts={};for(const e of state.estimates)counts[e.status]=(counts[e.status]||0)+1;return header('Auswertung','Bestätigte Trades getrennt von Rückblicken und OHLCV-Schätzungen.',button('evaluate','Marktverläufe auswerten'))+metricCards()+`<div class="grid-2">${panel('Realisierte Entwicklung',m.closed?'<canvas class="equity-chart" id="equity" width="800" height="170"></canvas>':empty('Noch keine belastbare Statistik','Keine künstliche Winrate. Erst bestätigte Abschlüsse zählen.'))}${panel('Risiko & Erwartungswert',`<div class="panel-body"><div class="context-grid">${[['Max. realisierter Drawdown',cash(m.maxDrawdown||0)],['Profit-Faktor',number(m.profitFactor)],['Erwartungswert / Trade',cash(m.expectancy)],['Geschlossene Trades',m.closed||0]].map(([k,v])=>`<div class="context-cell"><span>${k}</span><b>${v}</b></div>`).join('')}</div><p class="muted">${esc(m.note||'Keine Ergebnisse erfasst.')}</p></div>`)}${panel('Markt / Session',Object.keys(m.groups||{}).length?`<div class="table-wrap"><table><thead><tr><th>Segment</th><th>Trades</th><th>Netto</th><th>Ø R</th></tr></thead><tbody>${Object.entries(m.groups).map(([k,g])=>`<tr><td>${esc(k)}</td><td>${g.count}</td><td>${cash(g.net)}</td><td>${number(g.r/g.count)}R</td></tr>`).join('')}</tbody></table></div>`:empty('Noch keine Segmente','Gold Nacht und US-Sessions werden getrennt ausgewertet.'))}${panel('OHLCV-Schätzungen · separat',`<div class="panel-body"><div class="pill-group">${Object.entries(counts).map(([k,v])=>`<span class="badge-num">${esc(k)}: ${v}</span>`).join('')||'<span class="muted">Noch keine Schätzungen.</span>'}</div><p class="muted">Berührung ≠ Fill. Bei Entry/SL/TP in derselben Kerze oder Datenlücken wird keine gesicherte Reihenfolge behauptet. Auch ein eindeutig berechneter Verlauf ist nur ein Modell, kein tatsächlicher Trade.</p></div>`)}</div>`;}
function newsView(){return header('News & Makro','Öffentliche Headlines und Links · interne Themenregeln · keine Artikelvolltexte.',button('sync','↻ Quellen abrufen','gold-button')+button('news-add','＋ Quelle')+button('event','＋ Termin'))+`<div class="grid-2"><div class="stack">${miniNews()}</div><div class="stack">${marketContext()}${panel('Wirtschaftskalender',`<div class="panel-body"><div class="row">${[['today','Today'],['24h','Next 24h'],['7d','Next 7 days'],['high','High Impact']].map(([k,v])=>button('calendar-filter',v,calendarMode===k?'selected':'',k)).join('')}</div><p class="stat-warning">Abdeckung: ${esc(state.sync?.calendarStatus||'UNKNOWN')}</p></div>${eventList(150)}`)}${panel('Quellenstatus',`<div class="panel-body">${(state.sync?.reports||[]).map(r=>`<div class="source-row"><div><b>${esc(r.name)}</b><small>${esc(r.kind)} · ${berlinTime(r.lastSuccessAt)} ${esc(r.message||'')}</small></div>${chip(r.status,r.healthy?'green':'red')}</div>`).join('')}</div>`)}</div></div>`;}
function playbookView(){return header('Playbook & Lernspeicher','Unser Prozess bleibt manuell. Der Speicher lernt nicht heimlich neue Regeln.',button('playbook','＋ Playbook')+button('export-learning','Lerndaten ↓'))+`<div class="grid-2"><div class="stack">${state.playbooks.map(p=>panel(esc(p.name),`<div class="panel-body"><p class="note">${esc(p.description)}</p><div class="stack-small">${p.rules.map((r,i)=>`<div class="drawing-item"><span class="gold">${i+1}</span><span>${esc(r)}</span></div>`).join('')}</div><p class="muted">${esc(p.session||'Alle Sessions')}</p></div>`)).join('')}</div><div class="stack">${panel('Decision Snapshots',`<div class="panel-body"><div class="metric"><label>Unveränderlicher Entscheidungsstand</label><strong>${state.snapshots.length}</strong><small>Plan + damals bekannte Quellen + Hash</small></div><p class="muted">Vor dem Entry bekannte Informationen und spätere Ergebnisse bleiben getrennt. Rückblicke sind markiert und vom regulären Lernexport ausgeschlossen.</p><div class="learn-note">Master Brain: ${state.providers.brain?.configured?'Read-only JSONL-Schnittstelle aktiviert':'Anschluss vorbereitet, derzeit geschlossen'}. Kein Zugriff auf andere Brains, keine Orders, keine automatischen Änderungen. Ähnliche Fälle werden regelbasiert verglichen, nicht als trainierte Prognose ausgegeben.</div></div>`)}${panel('Review-Vorschläge',`<div class="panel-body">${state.proposals.length?state.proposals.map(p=>`<div class="review-card"><small>${esc(p.source)} · ${esc(p.status)}</small><p>${esc(p.note)}</p>${p.status==='PENDING'?button('proposal-accept','Übernehmen als geprüften Vorschlag','',p.id)+button('proposal-reject','Ablehnen','',p.id):''}</div>`).join(''):'<p class="muted">Noch keine Vorschläge. Auch akzeptierte Vorschläge überschreiben keine historischen Daten.</p>'}${button('proposal','＋ Vorschlag notieren')}</div>`)}</div></div>`;}
function settingsView(){return header('Daten & Setup','Marktdaten kommen unabhängig. Keine Zugangsdaten zu deiner Ausführungsplattform.',button('import','OHLCV importieren','gold-button')+button('export-json','Daten exportieren'))+`<div class="grid-2"><div class="stack">${panel('Verbindungen',`<div class="panel-body">${Object.entries(state.providers).map(([k,p])=>`<div class="source-row"><div><b>${esc({news:'Nachrichten',calendar:'Wirtschaftskalender',macro:'Renditen & Makro',history:'Futures-Historie',live:'Live-Marktdaten',brain:'Master Brain',broker:'Broker / Execution'}[k]||k)}</b><small>${esc(p.provider||p.type||p.mode||'')}</small></div>${chip(p.configured?'KONFIGURIERT':k==='broker'?'AUSGESCHLOSSEN':'NICHT VERBUNDEN',p.configured?'green':'')}</div>`).join('')}<p class="muted">Konfiguriert bedeutet nicht automatisch erreichbar oder lizenziert. Preise zeigen immer Quelle und Datenalter. Secrets werden nur als Server-ENV gesetzt, niemals im iPad gespeichert.</p>${button('sync','Quellen testen / abrufen')} ${button('history','Historie laden')}</div>`)}${panel('Importierte Daten',state.series.length?`<div class="table-wrap"><table><thead><tr><th>Kontrakt</th><th>Quelle</th><th>Kerzen</th><th>Letzte</th></tr></thead><tbody>${state.series.map(s=>`<tr><td>${esc(s.contract)}</td><td>${esc(s.source)} · ${s.resolution}s</td><td>${s.count}</td><td>${date(s.last)}</td></tr>`).join('')}</tbody></table></div>`:empty('Keine Kerzen gespeichert','Import akzeptiert exakte Futures-Kontrakte und ISO-Zeitstempel.'))}</div><div class="stack">${panel('Persönliche Risikovorgaben',`<div class="panel-body"><div class="context-grid">${[['Risiko / Idee',cash(state.settings.riskBudget)],['Gesamtverlust-Budget',cash(state.settings.lossBudget)],['Rundenziel',cash(state.settings.phaseTarget)],['Interner Feierabend',state.settings.sessionEnd]].map(([k,v])=>`<div class="context-cell"><span>${k}</span><b>${v}</b></div>`).join('')}</div><p class="muted">Eigene Richtwerte, keine automatische Prüfung von Prop-Bedingungen. Marktziele sind keine garantierten Erträge.</p>${button('settings','Einstellungen ändern')}</div>`)}${panel('Aktive Kontrakte',`<div class="panel-body"><p class="muted">Den tatsächlichen Handelsmonat selbst bestätigen. Es wird niemals still auf einen anderen Kontrakt gerollt.</p>${Object.entries(INSTRUMENTS).map(([k,s])=>`<div class="source-row"><b>${esc(s.name)}</b><span>${esc(currentContract(k)||'Nicht gewählt')}</span></div>`).join('')}${button('contracts','Kontrakte festlegen')}</div>`)}${panel('Quellenstatus',`<div class="panel-body">${(state.sync?.reports||[]).map(r=>`<div class="source-row"><div><b>${esc(r.name)}</b><small>${berlinTime(r.at)} ${esc(r.message||'')}</small></div>${chip(r.status,r.status==='OK'?'green':'red')}</div>`).join('')||'<p class="muted">Noch kein externer Abruf.</p>'}</div>`)}</div></div>`;}
async function render(){chart?.destroy();chart=null;tickers();$$('.tabs button').forEach(b=>b.classList.toggle('selected',b.dataset.view===view));const builders={overview,charts:()=>header('Charts & Orderblocks','Zeichnungen sind Analysen – keine Orders. Preise am Ausführungsort selbst prüfen.')+chartPanel()+`<div class="panel panel-body" style="margin-top:15px"><div id="drawings-list"></div></div>`,plans:planView,journal,analytics:analyticsView,news:newsView,playbook:playbookView,settings:settingsView};$('#view').innerHTML=builders[view]();if($('#chart-host'))await mountChart();if($('#equity'))drawEquity();}
function drawEquity(){const canvas=$('#equity'),c=canvas.getContext('2d'),points=state.metrics.curve||[];if(!points.length)return;const min=Math.min(0,...points.map(x=>x.value)),max=Math.max(1,...points.map(x=>x.value));c.clearRect(0,0,800,170);c.strokeStyle='#4bbfa1';c.lineWidth=3;c.beginPath();points.forEach((p,i)=>{const x=20+i/Math.max(1,points.length-1)*750,y=145-(p.value-min)/(max-min||1)*120;i?c.lineTo(x,y):c.moveTo(x,y);});c.stroke();}
async function mountChart(){const host=$('#chart-host');chart=new TradingChart(host,{timezone:state.settings.timezone,onDraw:async d=>{try{if(!currentContract())throw Error('Bitte zuerst exakten Kontrakt wählen.');const spec=INSTRUMENTS[instrument];d.points=d.points.map(p=>({...p,price:round(Math.round(p.price/spec.tick)*spec.tick,4)}));await api('drawing',{...d,contract:currentContract(),label:d.type==='zone'?($('#chart-side')?.value==='SHORT'?'Supply / Orderblock':'Demand / Orderblock'):'Level',side:$('#chart-side')?.value||'LONG'});state.drawings=(await api('bootstrap')).drawings;updateChart();notify('Zeichnung gespeichert.');}catch(e){notify(e.message,true);}}});chart.decimals=instrument==='MGC'?1:2;const s=bestSeries();if(s){try{const j=await api('candles',null,{contract:s.contract,source:s.source,resolution:String(s.resolution)});chartBars=aggregateCandles(j.bars,Math.max(timeframe,s.resolution/60));}catch(e){chartBars=[];notify(e.message,true);}}else chartBars=[];updateChart();}
function updateChart(){if(!chart)return;const end=Math.max(1,Math.round(chartBars.length*replay/100)),bars=chartBars.slice(0,end);const p=state.plans.find(x=>x.id===selectedPlan&&x.contract===currentContract());const cutoff=bars.at(-1)?.time;const drawings=state.drawings.filter(d=>d.contract===currentContract()&&(replay===100||!d.createdAt||d.createdAt<=cutoff));chart.setData(bars,drawings,p);if($('#chart-note'))$('#chart-note').textContent=replay<100?'REPLAY · '+date(cutoff)+' · spätere Zeichnungen ausgeblendet':'Exakter Kontrakt · OHLCV · keine Orderausführung';if($('#drawings-list'))$('#drawings-list').innerHTML=drawings.length?`<div class="row">${drawings.map(d=>`<div class="drawing-item"><span>${esc(d.label)} ${number(d.points[0].price)}</span>${button('drawing-edit','Bearbeiten','',d.id)}${button('drawing-delete','✕','',d.id)}</div>`).join('')}</div>`:'<p class="muted">Block: zwei Ecken tippen. Linie: Preis tippen. Zeichnen: frei mit Finger/Stift. Zeichnungen werden im eigenen Backend gespeichert.</p>';}
async function refresh(){if(loading)return;loading=true;try{state=await api('bootstrap');$('#connection-banner').className='notice '+(state.demo?'demo':'ok');$('#connection-banner').innerHTML=state.demo?'<span><b>DEMO · SYNTHETISCHE DATEN.</b> Keine echten Preise, Trades oder Nachrichten.</span>':`<span><b>Journal verbunden.</b> ${state.series.some(s=>s.source==='databento-live'&&Date.now()-Date.parse(s.last)<180000)?'Livebars empfangen.':'Kein bestätigter Livefeed – keine Livepreise angenommen.'}</span><span>${esc(state.mode)}</span>`;await render();}catch(e){const b=$('#connection-banner');b.className='notice error';b.innerHTML=`<span>${esc(e.message)}</span>${e.status===401?'<a href="/login.html">Anmelden ↗</a>':''}`;if(!$('#view').children.length)await render();}finally{loading=false;}}
// Background refresh never reloads the journal, chart, drawings or current view.
let contextLoading=false;
async function refreshContext(){
 if(loading||contextLoading||document.hidden||$('#modal').open)return;
 contextLoading=true;
 try{
  const next=await api('news');
  if(loading)return;
  for(const key of ['news','events','observations','context','sync','marketContext','marketContexts'])state[key]=next[key];
  // Render context markup off-screen; replace only its panels, never the chart.
  const template=document.createElement('template');template.innerHTML=view==='overview'?overview():view==='news'?newsView():view==='settings'?settingsView():'';
  const position={x:window.scrollX,y:window.scrollY};
  for(const old of $$('[data-context-panel]',$('#view'))){
   const replacement=template.content.querySelector('[data-context-panel="'+old.dataset.contextPanel+'"]');if(!replacement)continue;
   const scroll=$('.news-scroll',old)?.scrollTop||0;
   const focus=document.activeElement?.closest('[data-action]'),action=old.contains(focus)?{name:focus.dataset.action,id:focus.dataset.id}:null;
   old.replaceWith(replacement);
   const list=$('.news-scroll',replacement);if(list)list.scrollTop=scroll;
   if(action)$$('[data-action]',replacement).find(b=>b.dataset.action===action.name&&b.dataset.id===action.id)?.focus({preventScroll:true});
  }
  window.scrollTo(position.x,position.y);
 }catch(e){
  const radar=$('[data-context-panel="news"]');if(radar){let error=$('[data-refresh-error]',radar);if(!error){error=document.createElement('p');error.dataset.refreshError='';error.className='muted';radar.append(error);}error.textContent='News-Aktualisierung fehlgeschlagen. Letzter gespeicherter Stand bleibt sichtbar.';}
 }finally{contextLoading=false;}
}
function modal(title,html,onSubmit){$('#modal-title').textContent=title;$('#modal-body').innerHTML=html;$('#modal').showModal();const form=$('form',$('#modal-body'));if(form&&onSubmit)form.addEventListener('submit',async e=>{e.preventDefault();const submit=$('[type=submit]',form);submit.disabled=true;try{await onSubmit(Object.fromEntries(new FormData(form)),form);$('#modal').close();await refresh();}catch(err){let box=$('.form-error',form);if(!box){box=document.createElement('div');box.className='form-error';form.append(box);}box.textContent=err.message;}finally{submit.disabled=false;}});}
const formWrap=(html,label='Speichern')=>`<form>${html}<div class="form-error" role="alert"></div><div class="form-actions"><button type="button" data-action="close">Abbrechen</button><button type="submit" class="gold-button">${label}</button></div></form>`;
function planForm(copy=null){const p=copy||{},s=INSTRUMENTS[p.instrument||instrument],created=new Date(),expires=new Date(created);expires.setHours(...(state.settings.sessionEnd||'19:00').split(':').map(Number),0,0);if(expires<created)expires.setDate(expires.getDate()+1);let attached=[];modal(copy?'Plan als neue Entscheidung':'Limit-Trade planen',formWrap(`<div class="notice"><span>Dies speichert einen Plan. Es wird <b>keine Order gesendet</b>. Echte Ausführung bestätigst du separat.</span></div><div class="form-grid">${select('instrument','Markt',Object.entries(INSTRUMENTS).map(([k,v])=>[k,v.name+' · '+k]),p.instrument||instrument)}${field('contract','Exakter Kontrakt',p.contract||currentContract(), 'text','required placeholder="z. B. MGCZ6"')}${select('side','Richtung',[['LONG','Long · Buy Limit'],['SHORT','Short · Sell Limit']],p.side||'LONG')}${field('quantity','Anzahl Kontrakte',p.quantity||5,'number','required min="1" max="100" step="1"')}${field('entry','Limit-Preis',p.entry||'','number',`required step="${s.tick}"`)}${field('stop','Stop-Loss-Preis',p.stop||'','number',`required step="${s.tick}"`)}${field('target','Ziel-Preis',p.target||'','number',`required step="${s.tick}"`)}${field('costPerContract','Roundtrip-Kosten je Kontrakt (USD)',p.costPerContract||0,'number','min="0" step="0.01"')}${field('zoneLow','Block-Unterkante',p.zoneLow||'','number','required step="any"')}${field('zoneHigh','Block-Oberkante',p.zoneHigh||'','number','required step="any"')}${field('knownAt','Block bereits bekannt seit',localValue(p.knownAt||created),'datetime-local','required')}${field('expiresAt','Limit-Idee gültig bis',localValue(expires),'datetime-local','required')}${select('session','Session',['Nacht / Asien','Europa','US','Andere'],p.session||'Nacht / Asien')}${select('playbookId','Playbook',state.playbooks.map(p=>[p.id,p.name]),p.playbookId||state.playbooks[0]?.id)}${select('bias','News-/Makro-Bias',['LONG','SHORT','NEUTRAL'],p.bias||'NEUTRAL')}${field('plannedAt','Entscheidungszeit',localValue(),'datetime-local','required')}${textarea('reason','Warum dieses Level / dieser Move?',p.reason||'')}${textarea('invalidation','Was macht den Plan ungültig?',p.invalidation||'')}${textarea('counterArgument','Gegencheck · Argument gegen unsere Richtung',p.counterArgument||'')}${textarea('newsNote','Geprüfte News & Termine / bekannte Unsicherheiten',p.newsNote||'')}<div class="full checks">${DEFAULT_PLAYBOOK.rules.map((r,i)=>`<label><input type="checkbox" name="check-${i}">${esc(r)}</label>`).join('')}<label><input type="checkbox" name="retrospective"> Historischer Rückblick (nicht in Live-Statistik)</label></div><div class="full"><div id="plan-calc" class="calc-box">Preise eingeben, um SL und Risiko zu berechnen.</div><p class="muted">Gold-Anzeige: 1 persönlicher Pip = 0,1 Preisabstand. 1 MGC = 1 USD pro so definiertem Pip. Kein universeller CFD-Pip.</p></div>${textarea('overrideReason','Nur bei Abweichung: Warum Risiko/CRV bewusst anders?',p.overrideReason||'')}<div class="full file-drop"><label>Pre-Trade-Screenshot (optional) <input id="plan-image" type="file" accept="image/png,image/jpeg,image/webp"></label><p class="muted" id="image-status">Browser verkleinert das Bild. Kontonummern/Secrets vorher schwärzen.</p></div></div>`, 'Entscheidungs-Snapshot speichern'),async(data,form)=>{const body={...data,knownAt:formTime(data.knownAt),plannedAt:data.retrospective==='on'?formTime(data.plannedAt):new Date().toISOString(),expiresAt:formTime(data.expiresAt),retrospective:data.retrospective==='on',attachmentIds:attached,checks:DEFAULT_PLAYBOOK.rules.filter((r,i)=>data['check-'+i]==='on')};const result=await api('plans',body);notify('Plan gespeichert · Snapshot '+result.snapshot.hash.slice(0,10));});
 const form=$('form',$('#modal-body'));function calc(){const data=Object.fromEntries(new FormData(form)),spec=INSTRUMENTS[data.instrument];for(const k of ['entry','stop','target'])form.elements[k].step=spec.tick;const a={...data,entry:+data.entry,stop:+data.stop,target:+data.target,quantity:+data.quantity,costPerContract:+data.costPerContract};if(!a.entry||!a.stop||!a.target||a.entry===a.stop)return;const r=risk(a);$('#plan-calc').innerHTML=`<div><span>SL-ABSTAND</span><b>${r.stopUnits} ${r.unit}</b></div><div><span>RISIKO + KOSTEN</span><b>${cash(r.riskWithCosts)}</b></div><div><span>ZIEL NETTO</span><b>${cash(r.netReward)}</b></div><div><span>CRV BRUTTO</span><b>${number(r.rr)}R</b></div>`;}form.addEventListener('input',calc);form.elements.instrument.addEventListener('change',()=>{form.elements.contract.value=currentContract(form.elements.instrument.value);calc();});calc();$('#plan-image').addEventListener('change',async e=>{try{const a=await upload(e.target.files[0]);attached=[a.id];$('#image-status').textContent='Gespeichert: '+a.name;}catch(err){$('#image-status').textContent=err.message;}});}
async function upload(file){if(!file)throw Error('Datei fehlt.');if(file.size>15_000_000)throw Error('Quelldatei zu groß (15 MB).');const url=URL.createObjectURL(file);try{const img=await new Promise((resolve,reject)=>{const im=new Image();im.onload=()=>resolve(im);im.onerror=()=>reject(Error('Bild konnte nicht gelesen werden.'));im.src=url;});const scale=Math.min(1,1600/img.width,1200/img.height),canvas=document.createElement('canvas');canvas.width=img.width*scale;canvas.height=img.height*scale;canvas.getContext('2d').drawImage(img,0,0,canvas.width,canvas.height);let result=canvas.toDataURL('image/jpeg',.84);if(result.length>1200000)result=canvas.toDataURL('image/jpeg',.6);return await api('attachment',{name:file.name,data:result.split(',')[1]});}finally{URL.revokeObjectURL(url);}}
function reviewForm(kind='MORNING',planId=null){modal('Review festhalten',formWrap(`<div class="form-grid">${select('planId','Bezug',[['','Gesamte Session'],...state.plans.map(p=>[p.id,`${p.contract} ${p.side} · ${date(p.plannedAt)}`])],planId||'')}${select('kind','Review-Typ',['MORNING','EVENING','FINAL','NOTE','NO_FILL','CANCELLED','NO_TRADE','AMENDMENT'],kind)}${textarea('note','Was hat sich geändert? Entscheidung, Begründung und ggf. neue SL/TP-Preise.')}${select('rating','Prozessqualität (keine Gewinnwertung)',['0','1','2','3','4','5'],'0')}</div>`),async d=>{await api('review',d);notify('Review separat gespeichert. Originalentscheidung bleibt unverändert.');});}
function contextForm(){const c=state.context.find(c=>c.instrument===instrument)||{};modal('Abend- / Marktanalyse',formWrap(`<div class="form-grid">${select('instrument','Markt',Object.entries(INSTRUMENTS).map(([k,v])=>[k,v.name]),instrument)}${select('bias','Eigene Richtungsthese',['NEUTRAL','LONG','SHORT'],c.bias||'NEUTRAL')}${textarea('thesis','Struktur der letzten 24–48h, Vortag, Makro und News',c.thesis||'')}${textarea('counterArgument','Unabhängiger Gegencheck: Was spricht dagegen?',c.counterArgument||'')}<div class="checks full"><label><input name="eventsChecked" type="checkbox"> Kalender und bevorstehende News geprüft</label></div></div>`),async d=>{await api('context',{...d,eventsChecked:d.eventsChecked==='on'});notify('Zeitgestempelter Kontext gespeichert.');});}
async function detail(key){const p=state.plans.find(p=>p.id===key);if(!p)return;selectedPlan=p.id;const r=risk(p),a=actual(p),snap=state.snapshots.find(x=>x.planId===key),est=state.estimates.find(x=>x.planId===key);const reviews=state.reviews.filter(x=>x.planId===key);modal(`${INSTRUMENTS[p.instrument].name} · ${p.side} · Plan`,`${planCard(p)}<div class="row" style="margin-top:14px">${button('execution-entry','Echten Fill bestätigen','gold-button',key)}${button('execution-exit','Exit / Teil-Exit erfassen','',key)}${button('review-plan','Review','',key)}${button('copy-plan','Neue Plan-Kopie','',key)}${button('similar','Ähnliche Fälle','',key)}</div><h3 class="subhead">Entscheidung vor dem Trade</h3><p class="note">${esc(p.reason||'Keine Begründung erfasst.')}</p><p class="note">Invalidierung: ${esc(p.invalidation||'—')}<br>Gegenargument: ${esc(p.counterArgument||'—')}<br>News: ${esc(p.newsNote||'—')}</p><div class="snapshot-hash">Decision ${date(p.plannedAt)} · erfasst ${date(p.createdAt)}<br>SHA256 ${esc(snap?.hash||'—')}${p.retrospective?'<br>RÜCKBLICK: von Live-Metriken ausgeschlossen.':''}</div><h3 class="subhead">Tatsächliche Ausführung · ${esc(a.status)}</h3><p class="note">Offen: ${a.openQuantity} · realisiert netto: ${cash(a.net)} · initiales Risiko inkl. erfasster Kosten: ${cash(r.riskWithCosts)}</p><div class="table-wrap"><table><thead><tr><th>Aktion</th><th>Zeit</th><th>Preis</th><th>Anzahl</th><th>Gebühr</th><th></th></tr></thead><tbody>${state.executions.filter(e=>e.planId===key).map(e=>`<tr><td>${e.action}</td><td>${date(e.at)}</td><td>${number(e.price)}</td><td>${e.quantity}</td><td>${cash(e.fee)}</td><td>${button('void','Korrigieren','',e.id)}</td></tr>`).join('')}</tbody></table></div><h3 class="subhead">Marktverlauf · Schätzung, kein Fill-Beleg</h3>${est?`<p class="note">${esc(est.status)} · ${esc(est.coverage)} · ${est.barCount} Kerzen<br>MAE: ${number(est.mae)} ${r.unit} · MFE: ${number(est.mfe)} ${r.unit}<br>${esc(est.note||'')}<br>Quelle: ${esc(est.source)} · ${esc(est.contract)}</p>`:'<p class="muted">Noch nicht berechnet oder keine Kursabdeckung.</p>'}${button('evaluate-one','Mit Kursdaten auswerten','',key)}<h3 class="subhead">Screenshots & Reviews</h3><div class="image-grid">${p.attachmentIds.map(a=>`<a href="${apiURL('attachment',{id:a})}" target="_blank"><img loading="lazy" alt="Pre-Trade-Screenshot" src="${apiURL('attachment',{id:a})}"></a>`).join('')}</div><div class="file-drop" style="margin-top:12px"><label>Post-Trade-Bild hinzufügen <input type="file" id="post-image" accept="image/*"></label></div>${reviews.map(x=>`<article class="review-card"><small>${date(x.createdAt)} · ${esc(x.kind)}</small><p>${esc(x.note)}</p><div class="image-grid">${(x.attachmentIds||[]).map(a=>`<a href="${apiURL('attachment',{id:a})}" target="_blank" rel="noopener"><img alt="Review-Screenshot" src="${apiURL('attachment',{id:a})}"></a>`).join('')}</div></article>`).join('')}<div id="similar-result"></div>`);$('#post-image').onchange=async e=>{try{const image=await upload(e.target.files[0]);await api('review',{planId:key,kind:'NOTE',note:'Post-Trade-Screenshot',attachmentIds:[image.id]});notify('Bild und Review gespeichert.');await refresh();$('#modal').close();await detail(key);}catch(err){notify(err.message,true);}};}
function executionForm(key,action){const p=state.plans.find(p=>p.id===key);$('#modal').close();modal('Tatsächliche '+(action==='ENTRY'?'Ausführung':'Schließung')+' dokumentieren',formWrap(`<div class="notice"><span>Nur erfassen, was du wirklich ausgeführt hast. Keine Verbindung zum Broker.</span></div><div class="form-grid">${field('price','Tatsächlicher Ausführungspreis',action==='ENTRY'?p.entry:'','number','required step="any"')}${field('quantity','Ausgeführte Kontrakte',action==='ENTRY'?p.quantity:actual(p).openQuantity,'number','required min="1" step="1"')}${field('at','Ausführungszeit (Geräte-Ortszeit)',localValue(new Date(),true),'datetime-local','required step="0.001"')}${field('fee','Tatsächliche Gebühren für diesen Fill (USD)',0,'number','required min="0" step="0.01"')}${textarea('note','Notiz / Abweichung zum Plan')}<div class="full checks"><label><input type="checkbox" name="confirm" required> Ich bestätige diesen tatsächlichen Fill.</label></div></div>`),async d=>{await api('execution',{...d,action,planId:key,at:formTime(d.at),confirm:d.confirm==='on'});notify('Ausführung dokumentiert.');});}
function settingsForm(){const s=state.settings;modal('Persönliche Vorgaben',formWrap(`<div class="form-grid">${field('riskBudget','Risiko je Idee (USD)',s.riskBudget,'number','min="1"')}${field('maxConcurrentRisk','Gleichzeitig geplantes Risiko (USD)',s.maxConcurrentRisk,'number','min="1"')}${field('lossBudget','Verlustbudget (USD)',s.lossBudget,'number','min="1"')}${field('phaseTarget','Rundenziel (USD)',s.phaseTarget,'number','min="1"')}${field('maxPositionContracts','Persönliches Kontraktlimit',s.maxPositionContracts,'number','min="1" step="1"')}${field('sessionEnd','Eigener Feierabend',s.sessionEnd,'time')}${field('challengeLabel','Journal-/Challenge-Name',s.challengeLabel)}${field('phase','Runde',s.phase)}${field('timezone','Anzeige-Zeitzone',s.timezone)}${field('newsMinutes','News-Warnfenster in Minuten',s.newsMinutes,'number','min="1"')}</div><p class="muted">Keine verbindliche Auslegung eines Prop-Vertrags. Limits manuell mit gültigen Bedingungen abgleichen.</p>`),async d=>{await api('settings',d);notify('Vorgaben gespeichert.');});}
function contractsForm(){modal('Handelsmonate festlegen',formWrap(`<div class="notice"><span>Exakter Kontrakt statt Continuous/CFD. Daten und Plan müssen denselben Monat verwenden.</span></div><div class="form-grid">${Object.entries(INSTRUMENTS).map(([k,v])=>field(k,v.name+' · '+k,currentContract(k),'text',`placeholder="${k}Z6"`)).join('')}</div>`),async d=>{await api('settings',{contracts:Object.fromEntries(Object.entries(d).filter(([,v])=>v.trim()).map(([k,v])=>[k,v.toUpperCase().trim()]))});notify('Kontrakte gespeichert.');});}
function importForm(){modal('OHLCV-Kerzen importieren',formWrap(`<div class="notice"><span>Marktdaten-CSV, keine Brokerverbindung. Zeitstempel müssen UTC/Offset enthalten. Keine 1!- oder CFD-Daten als Micro-Fills ausgeben.</span></div><div class="form-grid">${select('instrument','Instrument',Object.entries(INSTRUMENTS).map(([k,v])=>[k,v.name]),instrument)}${field('contract','Exakter Kontrakt',currentContract(),'text','required')}${select('resolution','Ursprüngliche Kerzendauer (Sekunden)',['1','60','300','900','1800','3600'],'60')}${field('source','Datenquelle','manual-csv','text','required')}<div class="full file-drop"><input id="csv-file" type="file" accept=".csv,text/csv"><p class="muted">Spalten: time,open,high,low,close,volume<br>Beispiel: 2026-09-18T00:00:00Z,4400,4402,4399,4401,70<br>Maximal 10.000 Kerzen pro Upload.</p></div>${textarea('csv','CSV-Inhalt')}</div>`,'Importieren'),async d=>{const res=await api('ingest',d);notify(res.count+' Kerzen importiert.');});$('#csv-file').onchange=async e=>{if(e.target.files[0])$('#f-csv').value=await e.target.files[0].text();};}
function historyForm(){modal('Futures-Historie laden',formWrap(`<div class="notice"><span>Benötigt serverseitigen Schlüssel und lizenzierte Datennutzung. Databento prüft Kosten vor Abruf; Massive verwendet den bestehenden Tarif. Höchstens sieben Tage pro Request. Wiederholungen können erneut Provider-Kosten verursachen.</span></div><div class="form-grid">${select('provider','Provider',[['databento','Databento'],['massive','Massive']],state.providers.massive?.configured&&!state.providers.history?.configured?'massive':'databento')}${select('instrument','Markt',Object.entries(INSTRUMENTS).map(([k,v])=>[k,v.name]),instrument)}${field('contract','Exakter Provider-Kontrakt',currentContract(),'text','required')}${field('from','Von (Geräte-Ortszeit)',localValue(new Date(Date.now()-2*86400000)),'datetime-local','required')}${field('to','Bis',localValue(new Date(Date.now()-3600000)),'datetime-local','required')}</div>`,'Historie laden'),async d=>{const result=await api('history',{...d,from:formTime(d.from),to:formTime(d.to)});notify(`${result.count} Kerzen geladen (${result.source}).${Number.isFinite(result.estimatedCostUSD)?' Kostenprognose '+result.estimatedCostUSD+' USD.':''}`);});}
function newsForm(){modal('Quelle festhalten',formWrap(`<div class="form-grid">${field('title','Überschrift','','text','required')}${field('source','Quelle','','text','required')}${field('url','Original-Link (HTTPS)','','url','required')}${select('topic','Thema',['Gold','Makro','Zentralbanken','Geopolitik','Öl','Aktien','Andere'],'Makro')}${field('publishedAt','Veröffentlicht (wenn bekannt)','','datetime-local')}${textarea('note','Einordnung / Unsicherheit / Bedeutung für den Plan')}</div>`),async d=>{await api('news',{...d,publishedAt:d.publishedAt?formTime(d.publishedAt):null});notify('Quelle mit Erfassungszeit gespeichert.');});}
function eventForm(){modal('Wirtschaftstermin',formWrap(`<div class="form-grid">${field('title','Ereignis','','text','required')}${field('at','Zeit (Geräte-Ortszeit)',localValue(),'datetime-local','required')}${field('country','Land / Währung')}${select('impact','Bedeutung',['HIGH','MEDIUM','LOW'],'HIGH')}${field('url','Quelle','', 'url')}${field('forecast','Prognose')}${field('previous','Vorher')}${field('actual','Veröffentlicht / Ist')}</div>`),async d=>{await api('event',{...d,at:formTime(d.at)});notify('Termin gespeichert.');});}
function observationForm(){modal('Kontextwert dokumentieren',formWrap(`<div class="form-grid">${field('id','Kennung (z. B. DXY)','DXY','text','required')}${field('label','Anzeigename','Dollarindex','text','required')}${field('value','Wert','','number','step="any" required')}${field('unit','Einheit','Index')}${field('source','Quelle','','text','required')}${field('at','Zeitpunkt des Werts',localValue(),'datetime-local','required')}${field('url','Quellenlink','','url')}</div>`),async d=>{await api('observation',{...d,at:formTime(d.at)});notify('Wert als manuelle Beobachtung gespeichert.');});}
function playbookForm(){modal('Playbook hinzufügen',formWrap(`<div class="form-grid">${field('name','Name','','text','required')}${field('session','Session','Nacht / Asien')}${textarea('description','Beschreibung')}${textarea('rules','Regeln · eine pro Zeile')}</div>`),async d=>{await api('playbook',{...d,rules:d.rules.split('\n').filter(Boolean)});notify('Playbook gespeichert.');});}
function drawingForm(key){
 const d=state.drawings.find(x=>x.id===key);if(!d)return;
 modal('Zeichnung exakt einstellen',formWrap(`<div class="form-grid">${field('label','Bezeichnung',d.label)}${select('side','Bereich',[['LONG','Demand'],['SHORT','Supply']],d.side)}${d.points.slice(0,d.type==='path'?1:2).map((p,i)=>field('price'+i,'Preis '+(i+1),p.price,'number','required step="any"')+field('time'+i,'Zeit '+(i+1)+' (Gerät)',localValue(p.time),'datetime-local','required')).join('')}</div><p class="muted">Zeichnungsänderungen überschreiben keine bereits gespeicherten Decision Snapshots.</p>`),async data=>{
  const points=d.points.map((p,i)=>data['price'+i]!==undefined?{price:+data['price'+i],time:formTime(data['time'+i])}:p);
  await api('drawing',{...d,points,label:data.label,side:data.side});notify('Zeichnung aktualisiert.');
 });
}
async function action(name,key){if(name==='news-filter'){newsMode=key;return render();}if(name==='calendar-filter'){calendarMode=key;return render();}if(name==='close')return $('#modal').close();if(name==='new-plan')return planForm();if(name==='detail'){if($('#modal').open)$('#modal').close();return detail(key);}if(name==='copy-plan'){const p=state.plans.find(p=>p.id===key);$('#modal').close();return planForm(p);}if(name==='execution-entry'||name==='execution-exit')return executionForm(key,name==='execution-entry'?'ENTRY':'EXIT');if(name==='review-plan'){$('#modal').close();return reviewForm('MORNING',key);}if(name==='review-morning'||name==='review')return reviewForm();if(name==='no-trade')return reviewForm('NO_TRADE');if(name==='context')return contextForm();if(name==='settings')return settingsForm();if(name==='contracts')return contractsForm();if(name==='import')return importForm();if(name==='history')return historyForm();if(name==='news-add')return newsForm();if(name==='event')return eventForm();if(name==='observation')return observationForm();if(name==='playbook')return playbookForm();
 if(name==='sync'){notify('Quellen werden abgerufen …');const r=await api('sync',{});notify(`Abruf fertig: ${r.newsCount} Meldungen, ${r.eventCount} Termine. Quellenstatus beachten.`);return refresh();}
 if(name==='evaluate'||name==='evaluate-one'){await api('evaluate',key?{planId:key}:{});notify('Marktverläufe neu geschätzt. Keine echten Fills verändert.');await refresh();if(key){$('#modal').close();await detail(key);}return;}
 if(['export-json','export-csv','export-learning','report'].includes(name)){const url=name==='report'?apiURL('report'):apiURL('export',{format:name==='export-csv'?'csv':name==='export-learning'?'jsonl':'json'});const a=document.createElement('a');a.href=url;a.download='';document.body.append(a);a.click();a.remove();return;}
 if(name==='void'){const e=state.executions.find(x=>x.id===key);$('#modal').close();return modal('Ausführung korrigieren',formWrap(textarea('reason','Warum wird dieser Fill ungültig?'),'Korrektur speichern'),async d=>{await api('void-execution',{executionId:e.id,reason:d.reason});notify('Korrektur protokolliert. Original bleibt im Audit erhalten.');});}
 if(name==='proposal')return modal('Lernvorschlag',formWrap(textarea('note','Beobachtung oder möglicher Regelvorschlag')),async d=>{await api('proposals',d);notify('Vorschlag gespeichert, noch keine Handelsregel geändert.');});
 if(name==='proposal-accept'||name==='proposal-reject'){await api('proposals',{id:key,status:name==='proposal-accept'?'ACCEPTED':'REJECTED'});return refresh();}
 if(name==='similar'){const r=await api('similar',null,{id:key});$('#similar-result').innerHTML='<h3 class="subhead">Ähnliche historische Fälle · keine Prognose</h3>'+r.matches.map(m=>`<p class="note">${esc(m.session)} · ${m.side} · ${m.rr}R geplant · ${m.actual.status} · ${esc(m.reason)}</p>`).join('')+(r.matches.length?'':'<p class="muted">Noch keine vergleichbaren Fälle.</p>');return;}
 if(name.startsWith('chart-')){if(!chart)return;const op=name.slice(6);if(['zone','line','path','pan'].includes(op)){chart.tool(op);notify(op==='zone'?'Zwei Ecken des Blocks antippen.':op==='line'?'Preislinie durch Tippen setzen.':op==='path'?'Mit Finger/Stift zeichnen.':'Chart verschieben.');}else if(op==='in')chart.zoom(.8);else if(op==='out')chart.zoom(1.25);else if(op==='reset')chart.reset();else if(op==='save'){const a=document.createElement('a');a.href=chart.exportImage();a.download=`${currentContract()||'chart'}-analyse.png`;a.click();}else if(op==='undo'){const d=state.drawings.find(d=>d.contract===currentContract());if(d){await api('drawing',{id:d.id},{},'DELETE');state.drawings=state.drawings.filter(x=>x.id!==d.id);updateChart();}}return;}
 if(name==='drawing-edit')return drawingForm(key);
 if(name==='drawing-delete'){await api('drawing',{id:key},{},'DELETE');state.drawings=state.drawings.filter(x=>x.id!==key);updateChart();}
 if(name==='replay-step'){replay=Math.min(100,replay+100/Math.max(1,chartBars.length));$('#replay').value=replay;updateChart();}
}
document.addEventListener('click',e=>{const b=e.target.closest('[data-action]');if(b){e.preventDefault();Promise.resolve(action(b.dataset.action,b.dataset.id)).catch(err=>notify(err.message,true));return;}const t=e.target.closest('[data-view]');if(t){view=t.dataset.view;render().catch(e=>notify(e.message,true));return;}const ins=e.target.closest('[data-instrument]');if(ins){instrument=ins.dataset.instrument;replay=100;if(!['charts','overview'].includes(view))view='overview';render().catch(e=>notify(e.message,true));return;}const tf=e.target.closest('[data-tf]');if(tf){timeframe=+tf.dataset.tf;render().catch(e=>notify(e.message,true));}});
document.addEventListener('input',e=>{if(e.target.id==='replay'){replay=+e.target.value;updateChart();}});
document.addEventListener('change',e=>{if(e.target.id==='chart-market'){instrument=e.target.value;replay=100;render().catch(e=>notify(e.message,true));}});
$('.platform-toggle').onclick=()=>$('.platform-rail').classList.toggle('open');$('#modal-close').onclick=()=>$('#modal').close();$('#refresh').onclick=refresh;$('#create-plan').onclick=()=>planForm();
$('#clock').textContent=time(new Date().toISOString());
setInterval(()=>{$('#clock').textContent=time(new Date().toISOString());},1000);
setInterval(refreshContext,60000);
window.addEventListener('online',()=>{refreshContext();});
window.addEventListener('offline',()=>{const b=$('#connection-banner');b.className='notice error';b.textContent='Offline. Angezeigte Daten sind nicht aktuell. Neue Pläne werden nicht still lokal gespeichert.';});
refresh();
